function (param) {
                    var depth = param.treePathInfo.length;
                    if (depth === 2) {
                        return 'radial';
                    }
                    else if (depth === 3) {
                        return 'tangential';
                    }
                    else if (depth === 4) {
                        return '0';
                    }
                    return '';
                }
